algorithm SumOfVector
    dimension numbers[5] as integer;
    define i as integer;
    define total as integer;
    for i <- 0 to 4 step 1 do
        read numbers[i];
    endFor
    total <- 0;
    for i <- 0 to 4 step 1 do
        total <- total + numbers[i];
    endFor
    write total;
endAlgorithm
